(* [comment removed for export] *)
Definition amb_dims (w h l r t b Wd Hd : Z) : Prop :=
  (1 <= w <= 20000)%Z /\ (1 <= h <= 20000)%Z /\ (1 <= l <= 64)%Z /\ (1 <= r <= 64)%Z /\ (1 <= t <= 64)%Z /\ (1 <= b <= 64)%Z /\
  (l <= w)%Z /\ (r <= w)%Z /\ (t <= h)%Z /\ (b <= h)%Z /\ Wd = (w + l + r)%Z /\ Hd = (h + t + b)%Z.

