  Cok C -> W C A1 m md -> (s mod 16 = 0)%Z -> (c_top C - LSTK + AMB_STACK <= s)%Z -> (s <= c_top C)%Z ->
  armI isnull C A A1 m pixd Wd Hd data -> amfr m s ret rr w h -> POSTM C A s m0 m ->
  getr regs 2 = Z_to_bv 64 (s - 96) -> getr regs 9 = Z_to_bv 64 pixd -> getr regs 8 = Z_to_bv 64 t ->
  getr regs 19 = Z_to_bv 64 (l + j) -> getr regs 20 = Z_to_bv 64 (l - 1 - j) -> getr regs 21 = Z_to_bv 64 (r + l) ->
  getr regs 18 = Z_to_bv 64 b ->
  (forall x, In x CS6 -> getr regs x = getr rr x) ->
  (forall m' regs', W C A1 m' md -> armI isnull C A A1 m' pixd Wd Hd data -> amfr m' s ret rr w h -> POSTM C A s m0 m' ->
     getr regs' 2 = Z_to_bv 64 (s - 96) -> getr regs' 9 = Z_to_bv 64 pixd -> getr regs' 8 = Z_to_bv 64 t ->
     getr regs' 21 = Z_to_bv 64 (r + l) -> getr regs' 18 = Z_to_bv 64 b ->
     (forall x, In x CS6 -> getr regs' x = getr rr x) ->
     realizes SEGS (mkCfg (mkst regs' (0x1b824 : word) m' al_rom) md) S) ->
  realizes SEGS (mkCfg (mkst regs (0x1b7ec : word) m al_rom) md) S.
Proof.
